const listSubjectAssignments = `-- name: ListSubjectAssignments :many
SELECT id, tenant_id, subject_type, subject_id, role_id, scope_type, scope_resource_type, scope_resource_id, condition_policy_id, expires_at, source, created_at, created_by FROM role_assignments WHERE tenant_id = ? AND subject_type = ? AND subject_id IN (/*SLICE:subject_ids*/?)
`

type ListSubjectAssignmentsParams struct {
	TenantID    string
	SubjectType string
	SubjectIds  []string
}

func (q *Queries) ListSubjectAssignments(ctx context.Context, arg ListSubjectAssignmentsParams) ([]RoleAssignment, error) {
	query := listSubjectAssignments
	var queryParams []interface{}
	queryParams = append(queryParams, arg.TenantID)
	queryParams = append(queryParams, arg.SubjectType)
	if len(arg.SubjectIds) > 0 {
		for _, v := range arg.SubjectIds {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:subject_ids*/?", strings.Repeat(",?", len(arg.SubjectIds))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:subject_ids*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RoleAssignment{}
	for rows.Next() {
		var i RoleAssignment
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.SubjectType,
			&i.SubjectID,
			&i.RoleID,
			&i.ScopeType,
			&i.ScopeResourceType,
			&i.ScopeResourceID,
			&i.ConditionPolicyID,
			&i.ExpiresAt,
			&i.Source,
			&i.CreatedAt,
			&i.CreatedBy,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

